            $a->guidanceRules()->create($r);

        // ── ISI (Insomnia Severity Index) ──
        $isiOptions = [['label'=>'None','score'=>0],['label'=>'Mild','score'=>1],['label'=>'Moderate','score'=>2],['label'=>'Severe','score'=>3],['label'=>'Very Severe','score'=>4]];
        $a = Assessment::create(['title'=>'ISI Insomnia Index','description'=>'A 7-item measure of insomnia severity and sleep quality.','type'=>'isi','icon'=>'🌙','color'=>'purple','estimated_minutes'=>3,'category'=>'Sleep','question_count'=>7]);
