            $a->guidanceRules()->create($r);

        // ── ASRS (ADHD Screening) ──
        $a = Assessment::create(['title'=>'ASRS ADHD Screen','description'=>'A 6-item screening tool for adult ADHD symptoms.','type'=>'asrs','icon'=>'⚡','color'=>'orange','estimated_minutes'=>3,'category'=>'ADHD','question_count'=>6]);
        foreach(['How often do you have trouble wrapping up final details of a project','How often do you have difficulty getting things in order for a task','How often do you have problems remembering appointments or obligations','How often do you avoid starting a task that requires a lot of thought','How often do you fidget or squirm when you have to sit down for a long time','How often do you feel overly active and compelled to do things'] as $i=>$q)
