            $a->guidanceRules()->create($r);

        // ── Copenhagen Burnout Inventory (simplified) ──
        $burnoutOptions = [['label'=>'Never/Almost never','score'=>0],['label'=>'Seldom','score'=>1],['label'=>'Sometimes','score'=>2],['label'=>'Often','score'=>3],['label'=>'Always','score'=>4]];
        $a = Assessment::create(['title'=>'Burnout Assessment','description'=>'A questionnaire based on the Copenhagen Burnout Inventory to assess personal burnout.','type'=>'cbi','icon'=>'🔋','color'=>'red','estimated_minutes'=>4,'category'=>'Burnout','question_count'=>6]);
        foreach(['How often do you feel tired','How often are you physically exhausted','How often are you emotionally exhausted','How often do you think "I can\'t take it anymore"','How often do you feel worn out','How often do you feel weak and susceptible to illness'] as $i=>$q)
            $a->questions()->create(['text'=>"{$q}?",'order'=>$i+1,'options'=>$burnoutOptions]);
        foreach([['min_score'=>0,'max_score'=>7,'interpretation'=>'Low burnout','recommendation'=>'Your burnout levels are low. Keep maintaining work-life balance!'],['min_score'=>8,'max_score'=>15,'interpretation'=>'Moderate burnout','recommendation'=>'You show signs of moderate burnout. Take breaks, set boundaries, and prioritize self-care.'],['min_score'=>16,'max_score'=>24,'interpretation'=>'High burnout','recommendation'=>'Your burnout levels are high. Consider taking time off and consulting a professional about your work-life balance.']] as $r)
